12	declare_rule! {
13	    /// Disallow using `export` or `module.exports` in files containing tests
14	    ///
15	    /// This rule aims to eliminate duplicate runs of tests by exporting things from test files.
16	    /// If you import from a test file, then all the tests in that file will be run in each imported instance,
17	    /// so bottom line, don't export from a test, but instead move helper functions into a separate file when they need to be shared across tests.
18	    ///
19	    /// ## Examples
20	    ///
21	    /// ### Invalid
22	    ///
23	    /// ```js,expect_diagnostic
24	    /// export function myHelper() {}
25	    /// describe('a test', () => {
26	    ///     expect(1).toBe(1);
27	    /// });
28	    /// ```
29	    ///
30	    /// ### Valid
31	    ///
32	    /// ```js
33	    /// function myHelper() {}
34	    /// describe('a test', () => {
35	    ///     expect(1).toBe(1);
36	    /// });
37	    /// ```
38	    ///
39	    pub NoExportsInTest {
40	        version: "1.6.0",
41	        name: "noExportsInTest",
42	        recommended: true,
43	        source: RuleSource::EslintJest("no-export"),
44	        source_kind: RuleSourceKind::Inspired,
45	    }
46	}
