48	declare_node_union! {
49	    pub MaybeExport = JsExport | JsAssignmentExpression
50	}
51	
52	impl MaybeExport {
53	    fn is_export(&self) -> bool {
54	        match self {
55	            MaybeExport::JsExport(_) => true,
56	            MaybeExport::JsAssignmentExpression(assignment_expr) => {
57	                let left = assignment_expr.left().ok();
58	                left.and_then(|left| AnyJsMemberAssignment::try_cast_node(left).ok())
59	                    .is_some_and(|member_expr| {
60	                        let object = member_expr.object().ok();
61	                        object.is_some_and(|object| match object {
62	                            AnyJsExpression::JsIdentifierExpression(ident) => match member_expr {
63	                                AnyJsMemberAssignment::JsComputedMemberAssignment(_) => false,
64	                                AnyJsMemberAssignment::JsStaticMemberAssignment(static_member) => {
65	                                    // module.exports = {}
66	                                    let indent_text = ident.text();
67	                                    let member_text =
68	                                        static_member.member().map(|member| member.text());
69	                                    indent_text == "module"
70	                                        && member_text
71	                                            .is_ok_and(|member_text| member_text == "exports")
72	                                }
73	                            },
74	                            AnyJsExpression::JsStaticMemberExpression(member_expr) => {
75	                                // modules.exports.foo = {}, module.exports[foo] = {}
76	                                let object_text = member_expr.object().map(|object| object.text());
77	                                let member_text = member_expr.member().map(|member| member.text());
78	                                object_text.is_ok_and(|text| text == "module")
79	                                    && member_text.is_ok_and(|member_text| member_text == "exports")
80	                            }
81	                            _ => false,
82	                        })
83	                    })
84	            }
85	        }
86	    }
87	}
