12	declare_rule! {
13	    /// Disallow focused tests.
14	    ///
15	    /// Disabled test are useful when developing and debugging, because it forces the test suite to run only certain tests.
16	    ///
17	    /// However, in pull/merge request, you usually want to run all the test suite.
18	    ///
19	    /// ## Examples
20	    ///
21	    /// ### Invalid
22	    ///
23	    /// ```js,expect_diagnostic
24	    /// describe.only("foo", () => {});
25	    /// ```
26	    ///
27	    /// ```js,expect_diagnostic
28	    /// test.only("foo", () => {});
29	    /// ```
30	    ///
31	    /// ### Valid
32	    /// ```js
33	    /// test("foo", () => {});
34	    /// ```
35	    pub NoFocusedTests {
36	        version: "1.6.0",
37	        name: "noFocusedTests",
38	        recommended: true,
39	        source: RuleSource::EslintJest("no-focused-tests"),
40	        source_kind: RuleSourceKind::Inspired,
41	        fix_kind: FixKind::Unsafe,
42	    }
43	}
44	
45	const FUNCTION_NAMES: [&str; 3] = ["only", "fdescribe", "fit"];
46	const CALEE_NAMES: [&str; 3] = ["describe", "it", "test"];
47	
48	impl Rule for NoFocusedTests {
49	    type Query = Ast<JsCallExpression>;
50	    type State = TextRange;
51	    type Signals = Option<Self::State>;
52	    type Options = ();
53	
54	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
55	        let node = ctx.query();
56	        let callee = node.callee().ok()?;
57	
58	        if node.is_test_call_expression().ok()? {
59	            let callee = node.callee().ok()?;
60	            if callee.contains_a_test_pattern().ok()? {
61	                let function_name = callee.get_callee_member_name()?;
62	
63	                if FUNCTION_NAMES.contains(&function_name.text_trimmed()) {
64	                    return Some(function_name.text_trimmed_range());
65	                }
66	            }
67	        } else if let Some(expression) = callee.as_js_computed_member_expression() {
68	            let value_token = expression
69	                .as_fields()
70	                .object
71	                .ok()?
72	                .as_js_identifier_expression()?
73	                .name()
74	                .ok()?
75	                .value_token()
76	                .ok()?;
77	
78	            if expression.l_brack_token().is_ok()
79	                && expression.r_brack_token().is_ok()
80	                && CALEE_NAMES.contains(&value_token.text_trimmed())
81	            {
82	                if let Some(literal) = expression.member().ok()?.as_any_js_literal_expression() {
83	                    if literal.as_js_string_literal_expression().is_some()
84	                        && literal.to_string() == "\"only\""
85	                    {
86	                        return Some(expression.syntax().text_trimmed_range());
87	                    }
88	                }
89	            }
90	        }
91	
92	        None
93	    }
94	
95	    fn diagnostic(_: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
96	        Some(
97	            RuleDiagnostic::new(
98	                rule_category!(),
99	                range,
100	                markup! {
101	                    "Don't focus the test."
102	                },
103	            )
104	            .note("The 'only' method is often used for debugging or during implementation. It should be removed before deploying to production.")
105	            .note("Consider removing 'only' to ensure all tests are executed.")
106	        )
107	    }
108	
109	    fn action(ctx: &RuleContext<Self>, _: &Self::State) -> Option<JsRuleAction> {
110	        let node = ctx.query();
111	        let callee = node.callee().ok()?;
112	
113	        let mut mutation = ctx.root().begin();
114	
115	        if let Some(function_name) = callee.get_callee_member_name() {
116	            let replaced_function;
117	            match function_name.text_trimmed() {
118	                "only" => {
119	                    if let Some(expression) = callee.as_js_static_member_expression() {
120	                        let member_name = expression.member().ok()?;
121	                        let operator_token = expression.operator_token().ok()?;
122	                        mutation.remove_element(member_name.into());
123	                        mutation.remove_element(operator_token.into());
124	                    }
125	                }
126	                "fdescribe" => {
127	                    replaced_function = make::js_reference_identifier(make::ident("describe"));
128	                    mutation.replace_element(function_name.into(), replaced_function.into());
129	                }
130	                "fit" => {
131	                    replaced_function = make::js_reference_identifier(make::ident("it"));
132	                    mutation.replace_element(function_name.into(), replaced_function.into());
133	                }
134	                _ => {}
135	            };
136	        } else if let Some(expression) = callee.as_js_computed_member_expression() {
137	            let l_brack = expression.l_brack_token().ok()?;
138	            let r_brack = expression.r_brack_token().ok()?;
139	            let member = expression.member().ok()?;
140	            let expression = member.as_any_js_literal_expression()?;
141	            mutation.remove_element(NodeOrToken::Token(l_brack));
142	            mutation.remove_element(NodeOrToken::Node(expression.syntax().clone()));
143	            mutation.remove_element(NodeOrToken::Token(r_brack));
144	        };
145	
146	        Some(JsRuleAction {
147	            category: biome_analyze::ActionCategory::QuickFix,
148	            applicability: Applicability::MaybeIncorrect,
149	            message: markup! { "Remove focus from test." }.to_owned(),
150	            mutation,
151	        })
152	    }
