declare_rule! {
    /// Checks that the assertion function, for example `expect`, is placed inside an `it()` function call.
    ///
    /// Placing (and using) the `expect` assertion function can result in unexpected behaviors when executing your testing suite.
    ///
    /// The rule will check for the following assertion calls:
    /// - `expect`
    /// - `assert`
    /// - `assertEquals`
    ///
    /// However, the rule will ignore the following assertion calls:
    /// - `expect.any`
    /// - `expect.anything`
    /// - `expect.closeTo`
    /// - `expect.arrayContaining`
    /// - `expect.objectContaining`
    /// - `expect.stringContaining`
    /// - `expect.stringMatching`
    /// - `expect.extend`
    /// - `expect.addEqualityTesters`
    /// - `expect.addSnapshotSerializer`
    ///
    /// If the assertion function is imported, the rule will check if they are imported from:
    /// - `"chai"`
    /// - `"node:assert"`
    /// - `"node:assert/strict"`
    /// - `"bun:test"`
    /// - `"vitest"`
    /// - Deno assertion module URL
    ///
    /// Check the [tests](https://github.com/biomejs/biome/blob/main/crates/biome_js_analyze/tests/specs/nursery/noMisplacedAssertion/valid.js) for more examples.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// describe("describe", () => {
    ///     expect()
    /// })
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// import assert from "node:assert";
    /// describe("describe", () => {
    ///     assert.equal()
    /// })
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// import {test, expect} from "bun:test";
    /// expect(1, 2)
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// import {assertEquals} from "https://deno.land/std@0.220.0/assert/mod.ts";
    ///
    /// assertEquals(url.href, "https://deno.land/foo.js");
    /// Deno.test("url test", () => {
    ///     const url = new URL("./foo.js", "https://deno.land/");
    /// });
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// import assert from "node:assert";
    /// describe("describe", () => {
    ///     it("it", () => {
    ///         assert.equal()
    ///     })
    /// })
    /// ```
    ///
    /// ```js
    /// describe("describe", () => {
    ///     it("it", () => {
    ///         expect()
    ///     })
    /// })
    /// ```
    ///
    /// ```js
    /// test.each([1, 2, 3])('test', (a, b, expected) => {
    ///     expect(a + b).toBe(expected)
    /// })
    /// ```
    ///
    /// ```js
    /// import {test, expect} from "bun:test";
    /// test("test", () => {
    ///     expect(1, 2)
    /// })
    /// ```
    ///
    /// ```js
    /// import {assertEquals} from "https://deno.land/std@0.220.0/assert/mod.ts";
    ///
    /// Deno.test("url test", () => {
    ///     const url = new URL("./foo.js", "https://deno.land/");
    ///     assertEquals(url.href, "https://deno.land/foo.js");
    /// });
    /// ```
    ///
    pub NoMisplacedAssertion {
        version: "1.8.0",
        name: "noMisplacedAssertion",
        recommended: false,
        source: RuleSource::EslintJest("no-standalone-expect"),
        source_kind: RuleSourceKind::Inspired,
    }
}

/// Assertion function names that are recognized by the rule.
const ASSERTION_FUNCTION_NAMES: [&str; 3] = ["expect", "assert", "assertEquals"];

/// Module specifiers that are recognized as sources of assertion functions.
const SPECIFIERS: [&str; 5] = [
    "chai",
    "node:assert",
    "node:assert/strict",
    "bun:test",
    "vitest",
];

impl Rule for NoMisplacedAssertion {
    type Query = Semantic<JsCallExpression>;
    type State = JsReferenceIdentifier;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let query = ctx.query();
        let callee = query.callee().ok()?;

        // Extract the identifier used to reference the assertion function.
        // - `expect(...)` and `assertEquals(...)` are plain identifiers.
        // - `assert.equal(...)` is a member expression whose object is the identifier.
        let reference = assertion_reference(&callee)?;
        let name = reference.value_token().ok()?;
        let name = name.text_trimmed();

        if !ASSERTION_FUNCTION_NAMES.contains(&name) {
            return None;
        }

        // If the assertion is nested inside a `it()`, `test()` or `Deno.test()`
        // call, then it is correctly placed and shouldn't be reported.
        let is_inside_test_call = query
            .syntax()
            .ancestors()
            .filter_map(JsCallExpression::cast)
            .any(|call| is_it_test_or_deno_test_call(&call));

        if is_inside_test_call {
            return None;
        }

        // Now determine whether the identifier truly refers to an assertion
        // function: either an unresolved global with a recognized name, or a
        // binding imported from a recognized module specifier.
        let model = ctx.model();
        let is_assertion = match model.binding(&reference) {
            // Unresolved global that matches a recognized assertion name.
            None => true,
            Some(binding) => binding
                .syntax()
                .ancestors()
                .find_map(JsImport::cast)
                .and_then(|import| import.source_text().ok())
                .is_some_and(|source| is_supported_specifier(source.text())),
        };

        is_assertion.then_some(reference)
    }

    fn diagnostic(_: &RuleContext<Self>, reference: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                reference.range(),
                markup! {
                    "The assertion isn't inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
                },
            )
            .note(markup! {
                "This will result in unexpected behaviours from your test suite."
            })
            .note(markup! {
                "Move the assertion inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
            }),
        )
    }
}

/// Returns the reference identifier of a recognized assertion callee.
///
/// It handles direct calls such as `expect(...)` and `assertEquals(...)`, as
/// well as member expressions such as `assert.equal(...)`.
fn assertion_reference(callee: &AnyJsExpression) -> Option<JsReferenceIdentifier> {
    match callee.clone().omit_parentheses() {
        AnyJsExpression::JsIdentifierExpression(identifier) => identifier.name().ok(),
        AnyJsExpression::JsStaticMemberExpression(member) => member
            .object()
            .ok()?
            .omit_parentheses()
            .as_js_identifier_expression()?
            .name()
            .ok(),
        _ => None,
    }
}

